/**
 * P1691 — event banners are generated by one function, `generate-banner`.
 *
 * The earlier event-only banner function is retired: its directory is gone, nothing deployable
 * imports or lists it, and the app asks `generate-banner` for event banners. The smoke table's
 * match with the function directories is pinned separately (p890-edge-function-smoke.test.ts).
 *
 * STRUCTURAL ONLY: source text and the file tree, nothing is called.
 */
import { describe, it, expect } from 'vitest';
import { existsSync, readFileSync, readdirSync, statSync } from 'fs';
import { join, resolve } from 'path';

const ROOT = resolve(__dirname, '../..');
const FUNCTIONS = join(ROOT, 'supabase/functions');
const RETIRED = 'generate-event-banner';

function sourceFiles(dir: string): string[] {
  return readdirSync(dir).flatMap((name) => {
    const path = join(dir, name);
    if (statSync(path).isDirectory()) return sourceFiles(path);
    return /\.(ts|json|mjs)$/.test(name) ? [path] : [];
  });
}

describe('P1691: one banner function', () => {
  it('the retired function has no directory', () => {
    expect(existsSync(join(FUNCTIONS, RETIRED))).toBe(false);
    // The scan below is not blind: the current function is found by the same walk.
    expect(readdirSync(FUNCTIONS)).toContain('generate-banner');
  });

  it('no function source names it, apart from one comment kept in a live function', () => {
    const mentions = sourceFiles(FUNCTIONS)
      .filter((f) => readFileSync(f, 'utf8').includes(RETIRED))
      .map((f) => f.slice(FUNCTIONS.length + 1));
    // transcribe-slice/index.ts keeps a comment that names it: editing that file would change
    // the deploy hash of a live function for a comment.
    expect(mentions).toEqual(['transcribe-slice/index.ts']);
    const kept = readFileSync(join(FUNCTIONS, 'transcribe-slice/index.ts'), 'utf8')
      .split('\n')
      .filter((line) => line.includes(RETIRED));
    for (const line of kept) expect(line.trimStart().startsWith('//'), line).toBe(true);
  });

  it('the smoke table does not list it', () => {
    expect(readFileSync(join(ROOT, 'scripts/edge-function-smoke.mjs'), 'utf8')).not.toContain(RETIRED);
  });

  it('the app asks generate-banner for banners, and that function accepts events', () => {
    const client = readFileSync(join(ROOT, 'src/app/prototypes/events/banner-utils.ts'), 'utf8');
    expect(client).toContain('/functions/v1/generate-banner`');
    expect(client).not.toContain(RETIRED);
    const fn = readFileSync(join(FUNCTIONS, 'generate-banner/index.ts'), 'utf8');
    expect(fn).toMatch(/VALID_ENTITY_TYPES: EntityType\[\] = \[[^\]]*'event'/);
  });
});
